"""Código R de cada gráfico mostrado en las láminas 03 y 06."""
from html import escape
EXPLORACION = [('wage · Histograma', 'hist(datos$wage, breaks = seq(0, 26, by = 2), right = FALSE,\n     col = "#0160a0", border = "white", main = "Salario por hora",\n     xlab = "USD de 1976", ylab = "Frecuencia (personas)")'), ('educ · Gráfico de barras', 'anios <- seq(min(datos$educ), max(datos$educ))\nfrecuencias <- table(factor(datos$educ, levels = anios))\nbarplot(frecuencias, col = "#0160a0", border = "white",\n        main = "educ", xlab = "Años", ylab = "Frecuencia (personas)")'), ('exper · Gráfico de barras', 'anios <- seq(min(datos$exper), max(datos$exper))\nfrecuencias <- table(factor(datos$exper, levels = anios))\nbarplot(frecuencias, col = "#e12523", border = "white",\n        main = "exper", xlab = "Años", ylab = "Frecuencia (personas)")'), ('tenure · Gráfico de barras', 'anios <- seq(min(datos$tenure), max(datos$tenure))\nfrecuencias <- table(factor(datos$tenure, levels = anios))\nbarplot(frecuencias, col = "#00875a", border = "white",\n        main = "tenure", xlab = "Años", ylab = "Frecuencia (personas)")'), ('female · Gráfico circular', 'frecuencias <- table(factor(datos$female, levels = c(0, 1)))\netiquetas <- c("Hombre (0)", "Mujer (1)")\nporcentajes <- round(100 * frecuencias / sum(frecuencias), 1)\npie(frecuencias, labels = paste(etiquetas, porcentajes, "%"),\n    col = c("#0160a0", "#f8c751"), main = "female")'), ('married · Gráfico circular', 'frecuencias <- table(factor(datos$married, levels = c(0, 1)))\netiquetas <- c("No casado/a (0)", "Casado/a (1)")\nporcentajes <- round(100 * frecuencias / sum(frecuencias), 1)\npie(frecuencias, labels = paste(etiquetas, porcentajes, "%"),\n    col = c("#0160a0", "#f8c751"), main = "married")')]
BOXPLOTS = [('educ · Boxplot del salario', 'grupo <- factor(datos$educ >= 16, levels = c(FALSE, TRUE),\n                labels = c("Menos de 16 años", "16 años o más"))\nboxplot(datos$wage ~ grupo, col = c("#0160a0", "#f8c751"),\n        main = "Salario según educ", xlab = "Grupo",\n        ylab = "Salario por hora (USD de 1976)")'), ('female · Boxplot del salario', 'grupo <- factor(datos$female, levels = c(0, 1),\n                labels = c("Hombre (0)", "Mujer (1)"))\nboxplot(datos$wage ~ grupo, col = c("#0160a0", "#f8c751"),\n        main = "Salario según female", xlab = "Grupo",\n        ylab = "Salario por hora (USD de 1976)")'), ('married · Boxplot del salario', 'grupo <- factor(datos$married, levels = c(0, 1),\n                labels = c("No casado/a (0)", "Casado/a (1)"))\nboxplot(datos$wage ~ grupo, col = c("#0160a0", "#f8c751"),\n        main = "Salario según married", xlab = "Grupo",\n        ylab = "Salario por hora (USD de 1976)")')]

def render_codigos(items):
 return '<h4>Códigos en R de cada gráfico</h4><p>Ejecuta primero la carga de datos de la lámina 02. Cada bloque reproduce un gráfico con las mismas variables, agrupaciones y colores.</p>'+''.join('<details class="solution"><summary>'+escape(title)+'</summary><div class="solution-body"><div class="code-head"><span>R</span><button type="button" class="copy">Copiar código</button></div><pre><code>'+escape(code)+'</code></pre></div></details>' for title,code in items)
